const item = $json;
const instructions = `Sen Emre Cancioglu icin Turkce teknik LinkedIn taslagi yenileyen bir editorsun. Yalnizca verilen evidence_item icindeki bilgileri gercek calisma veya sonuc olarak kullan. Yapilmamis isi yapilmis gibi anlatma; yeni metrik, musteri, tesis, odul, tarih, arac veya sonuc uretme. proof_level=idea ise ogretici veya gorus dili kullan. kind=lab_demo ise demo, simulasyon veya sentetik veri oldugunu acikca belirt. confidentiality=anonymize ise sirket, tesis, hat, musteri ve kisi adi verme. Her gecmis zamanli veya olculebilir iddiayi claims listesine ekle. Turkce, dogal ve teknik fakat anlasilir yaz. 900-1500 karakter hedefle, en fazla 5 hashtag ve tek bir samimi soru kullan. Onceki taslagi farkli bir anlatim, acilis ve paragraf yapisiyla yeniden yaz. Kanit disina cikma.`;
const riskCodes = ['PRIVATE_EVIDENCE','CONFIDENTIAL_DETAIL','UNMAPPED_CLAIM','UNSUPPORTED_METRIC','DEMO_NOT_DISCLOSED','EVIDENCE_ID_MISMATCH','ORGANIZATION_NAME_EXPOSED','CAUSALITY_OVERCLAIM'];
const schema = { type: 'object', additionalProperties: false, properties: { pillar: { type: 'string', enum: ['OT_VERI_MIMARISI','ENDUSTRIYEL_AI','ENERJI_SURDURULEBILIRLIK','URETIMDE_GENAI','OT_SIBER_GUVENLIK','TEKNIK_LIDERLIK'] }, hook: { type: 'string' }, body: { type: 'string' }, cta: { type: 'string' }, hashtags: { type: 'array', items: { type: 'string' } }, claims: { type: 'array', items: { type: 'object', additionalProperties: false, properties: { claim: { type: 'string' }, evidence_id: { type: 'string' }, allowed: { type: 'boolean' }, reason: { type: 'string' } }, required: ['claim','evidence_id','allowed','reason'] } }, image_brief: { type: 'string' }, risk_flags: { type: 'array', items: { type: 'string', enum: riskCodes } } }, required: ['pillar','hook','body','cta','hashtags','claims','image_brief','risk_flags'] };
const evidence = { id: item.evidence_id, kind: item.kind, title: item.title, situation: item.situation, action_text: item.action_text, result_text: item.result_text, source_ref: item.source_ref, proof_level: item.proof_level, confidentiality: item.confidentiality, approved_claims: item.approved_claims, tags: item.tags };
const previous = { pillar: item.current_pillar, hook: item.current_hook, body: item.current_body, cta: item.current_cta, hashtags: item.current_hashtags, image_brief: item.current_image_brief };
return [{ json: { request_body: { model: 'gpt-6.1-terra', reasoning: { effort: 'low' }, instructions, input: [{ role: 'user', content: [{ type: 'input_text', text: `evidence_item:\n${JSON.stringify(evidence)}\n\nonceki_taslak:\n${JSON.stringify(previous)}` }] }], text: { format: { type: 'json_schema', name: 'linkedin_regenerated_draft', strict: true, schema } }, store: false } } }];

const requestBody = { ...$json.request_body };
requestBody.instructions = `${requestBody.instructions}\nTelegram'da gorsel, tam metin ve dugmeler tek mesajda gosterilecek. hook, body ve cta alanlarinin toplam uzunlugu 650-780 karakter arasinda olmali; 780 karakteri kesinlikle asma. Kaynak URL ve hashtagler bu sinira dahil degildir.`;
return [{ json: { request_body: requestBody } }];

const response = $json;
if (response.error) throw new Error(`OpenAI error: ${JSON.stringify(response.error)}`);
const message = (response.output ?? []).find((item) => item.type === 'message');
const outputText = message?.content?.find((item) => item.type === 'output_text')?.text;
if (!outputText) throw new Error('OpenAI output_text bulunamadi');
const draft = JSON.parse(outputText);
const request = $('Claim Regeneration').first().json;
if (!Array.isArray(draft.hashtags) || draft.hashtags.length > 5) throw new Error('Hashtag siniri asildi');
if (!Array.isArray(draft.claims) || !Array.isArray(draft.risk_flags)) throw new Error('Gecersiz claims veya risk_flags');
for (const claim of draft.claims) { if (claim.evidence_id !== request.evidence_id) { claim.allowed = false; claim.reason = 'Evidence ID eslesmiyor'; draft.risk_flags.push('EVIDENCE_ID_MISMATCH'); } }
if (draft.claims.some((claim) => !claim.allowed)) draft.risk_flags.push('UNMAPPED_CLAIM');
const text = `${draft.hook}\n${draft.body}\n${draft.cta}`;
if (request.kind === 'lab_demo' && !/(demo|simulasyon|sentetik)/i.test(text)) draft.risk_flags.push('DEMO_NOT_DISCLOSED');
const risks = [...new Set(draft.risk_flags.filter(Boolean))];
return [{ json: { event_id: request.event_id, event_type: request.event_type, post_id: request.current_post_id, evidence_id: request.evidence_id, pillar: draft.pillar, hook: draft.hook.trim(), body: draft.body.trim(), cta: draft.cta.trim(), hashtags: draft.hashtags, claims: draft.claims, image_brief: draft.image_brief.trim(), risk_flags: risks, approval_status: risks.length ? 'blocked' : 'needs_review', text_model: response.model ?? 'gpt-6.1-terra', openai_response_id: response.id ?? null, token_usage: response.usage ?? null } }];

const draft = { ...$json };
const sourceRef = String($('Claim Regeneration').first().json.source_ref || '').trim();
const combined = `${draft.hook || ''} ${draft.body || ''} ${draft.cta || ''}`;
if (/^https?:\/\//i.test(sourceRef) && !combined.includes(sourceRef)) {
  draft.cta = `${String(draft.cta || '').trim()}\n\nKaynak: ${sourceRef}`.trim();
}
return [{ json: draft }];
